INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4857025, 701148, 24896, '<td valign="top">This was one I wish I got back to comment on so I''m glad you posted it. Take the challenge out and this is an 11/10 in my books. It''s awesomely perfect. Almost perfect exposure (just a few very small highlights), DOF+, SOO SHARP+, Comp+, smoooooth clean boken+, and the spiders shadow gives it the +1.<br/> <br/>I had a really hard time trying to put a score on it. I ended up voting 5. To me it just wasn''t hot. But is an awesome shot, I wonder how it would have done in a FS!? Scott<br/></td>', 'This was one I wish I got back to comment on so I''m glad you posted it. Take the challenge out and this is an 11/10 in my books. It''s awesomely perfect. Almost perfect exposure (just a few very small highlights), DOF+, SOO SHARP+, Comp+, smoooooth clean boken+, and the spiders shadow gives it the +1. I had a really hard time trying to put a score on it. I ended up voting 5. To me it just wasn''t hot. But is an awesome shot, I wonder how it would have done in a FS!? Scott', '2008-08-01 17:26:15.000000', NULL, 0),
